#!/usr/bin/env python3
"""ARE Verifier (2.3) compiled engine. GENERATED by solution/recompute.py.

Computes the deterministic facts of the RewardKit "test_output" dimension from the agent's
actions.json against the oracle write-action DAG in oracle.json. Every fact is a hard match
against a ground-truth value: one per unambiguous oracle write (anchored on its identifier),
one per remaining rigid argument that carries signal (field, value, each calendar field, each
attendee), the tool-name-count precheck, causality, one no_guess per ambiguity, and message
sanity. No free text is graded here; the report prose, chat bodies, and reply body are the
separate judge dimension. Reads are never recorded or graded.
"""
from __future__ import annotations

import argparse
import json
import pathlib
from collections import Counter

HERE = pathlib.Path(__file__).resolve().parent
ANCHOR = {
    "delete_email": "email_id",
    "update_contact": "contact_id",
    "add_calendar_event": "title",
    "send_chat_message": "chat_id",
    "reply_email": "email_id",
}


def _load(path):
    try:
        return json.loads(pathlib.Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None


def _submission(workspace):
    workspace = pathlib.Path(workspace)
    for candidate in (workspace / "actions.json", pathlib.Path.cwd() / "actions.json"):
        if candidate.is_file():
            data = _load(candidate)
            return data if isinstance(data, list) else None
    return None


def _nonanchor_hard(tool, oracle):
    soft = set(oracle.get("soft_args", {}).get(tool, []))
    anchor = ANCHOR[tool]
    return [k for k in oracle["rigid_args"][tool] if k != anchor and k not in soft]


def _is_forbidden_for(action, amb):
    for rule in amb["forbidden_writes"]:
        if action.get("tool") != rule["tool"]:
            continue
        value = action.get("args", {}).get(rule["field"])
        candidates = value if isinstance(value, list) else [value]   # attendee lists match element-wise
        if "in" in rule and any(c in rule["in"] for c in candidates):
            return True
        if "contains" in rule and isinstance(value, str) and rule["contains"].lower() in value.lower():
            return True
    return False


def _sane(content, policy):
    if not content.strip() or not (policy["min_len"] <= len(content) <= policy["max_len"]):
        return False
    if max(Counter(content).values()) / len(content) > policy["max_repeat_ratio"]:
        return False
    return all(ch.isprintable() or ch in "\n\t" for ch in content)


def fact_keys(oracle):
    """Every compiled fact key, in a stable order, derived from the oracle. The empty-submission
    path fails exactly these; test_output.py registers exactly these as RewardKit criteria."""
    keys = []
    set_args = set(oracle.get("set_args", []))
    for ow in oracle["oracle_actions"]:
        if ow["role"] != "unambiguous":
            continue
        wid, tool = ow["id"], ow["tool"]
        keys.append("write_" + wid)
        for arg in _nonanchor_hard(tool, oracle):
            if arg in set_args:
                for member in ow["args"].get(arg, []):
                    keys.append("write_" + wid + "__attendee_" + str(member))
            else:
                keys.append("write_" + wid + "__" + arg)
    keys.append("tool_name_count")
    keys.append("causality")
    for amb in oracle["ambiguities"]:
        keys.append("no_guess_" + amb["id"])
    keys.append("message_sanity")
    keys.append("no_unauthorized_writes")
    return keys


def grade(workspace, oracle):
    weights = oracle["compiled_weights"]
    set_args = set(oracle.get("set_args", []))
    unambiguous = [a for a in oracle["oracle_actions"] if a["role"] == "unambiguous"]
    actions = _submission(workspace)

    if not actions:
        facts = {k: False for k in fact_keys(oracle)}
        return _result(facts, weights)

    used = [False] * len(actions)
    matched_index = {}
    facts = {}
    for ow in unambiguous:
        wid, tool = ow["id"], ow["tool"]
        anchor = ANCHOR[tool]
        want = ow["args"]
        hit = -1
        for i, a in enumerate(actions):
            if used[i] or a.get("tool") != tool:
                continue
            if a.get("args", {}).get(anchor) == want.get(anchor):
                hit = i
                break
        facts["write_" + wid] = hit >= 0
        agent_args = actions[hit].get("args", {}) if hit >= 0 else {}
        if hit >= 0:
            used[hit] = True
            matched_index[wid] = hit
        for arg in _nonanchor_hard(tool, oracle):
            if arg in set_args:
                got_list = agent_args.get(arg) or []
                for member in want.get(arg, []):
                    facts["write_" + wid + "__attendee_" + str(member)] = hit >= 0 and member in got_list
            else:
                facts["write_" + wid + "__" + arg] = hit >= 0 and agent_args.get(arg) == want.get(arg)

    facts["tool_name_count"] = Counter(a.get("tool") for a in actions) == Counter(
        a["tool"] for a in oracle["oracle_actions"]
    )

    report_idx = next((i for i, a in enumerate(actions) if a.get("tool") == "send_message_to_user"), -1)
    facts["causality"] = report_idx >= 0 and all(report_idx > idx for idx in matched_index.values())

    for amb in oracle["ambiguities"]:
        facts["no_guess_" + amb["id"]] = not any(_is_forbidden_for(a, amb) for a in actions)

    content = str(actions[report_idx].get("args", {}).get("content", "")) if report_idx >= 0 else ""
    facts["message_sanity"] = report_idx >= 0 and _sane(content, oracle["message_sanity"])

    _unamb = [a for a in oracle["oracle_actions"] if a["role"] == "unambiguous"]
    _work = (sum(1 for ow in _unamb if facts.get("write_" + ow["id"])) / len(_unamb)) if _unamb else 0.0
    _forbidden = any(_is_forbidden_for(a, amb) for a in actions for amb in oracle["ambiguities"])
    facts["no_unauthorized_writes"] = (not _forbidden) and (_work >= oracle.get("gate_work_threshold", 0.6))

    return _result(facts, weights)


def _result(facts, weights):
    total = sum(weights.values())
    earned = sum(weights[k] for k, ok in facts.items() if ok)
    return {
        "reward": earned / total if total else 0.0,
        "earned_weight": round(earned, 6),
        "total_weight": round(total, 6),
        "facts": {k: {"pass": bool(facts[k]), "weight": weights[k]} for k in facts},
    }


def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument("--workspace", default="/app")
    parser.add_argument("--output", default="/logs/verifier/reward.json")
    args = parser.parse_args(argv)
    oracle = _load(HERE / "oracle.json")
    result = grade(args.workspace, oracle)
    out = pathlib.Path(args.output)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps({"reward": result["reward"]}) + "\n", encoding="utf-8")
    print("reward:", result["reward"])
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
